"""Versioned definitions, tool invocations, model jobs and operating limits."""
SCHEMA='''
CREATE TABLE IF NOT EXISTS definitions(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,kind TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL,active_version INTEGER,enabled INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS definition_versions(definition_id TEXT NOT NULL REFERENCES definitions(id),version INTEGER NOT NULL,state TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,content_hash TEXT NOT NULL,data TEXT NOT NULL,change_note TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,published_at TEXT,PRIMARY KEY(definition_id,version));
CREATE TRIGGER IF NOT EXISTS published_definition_immutable BEFORE UPDATE ON definition_versions WHEN OLD.state IN ('PUBLISHED','DISABLED') AND (NEW.data!=OLD.data OR NEW.content_hash!=OLD.content_hash) BEGIN SELECT RAISE(ABORT,'immutable published definition'); END;
CREATE TABLE IF NOT EXISTS definition_debugs(id TEXT PRIMARY KEY,definition_id TEXT NOT NULL,definition_version INTEGER NOT NULL,revision INTEGER NOT NULL,content_hash TEXT NOT NULL,actor_id TEXT NOT NULL,project_id TEXT,state TEXT NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS definition_releases(id TEXT PRIMARY KEY,definition_id TEXT NOT NULL,version INTEGER NOT NULL,action TEXT NOT NULL,actor_id TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tool_invocations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,actor_id TEXT NOT NULL,run_id TEXT,tool_id TEXT NOT NULL,tool_version INTEGER NOT NULL,node TEXT NOT NULL,input_hash TEXT NOT NULL,state TEXT NOT NULL,summary TEXT NOT NULL,idempotency_key TEXT,result_ref TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS model_jobs(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,actor_id TEXT NOT NULL,owner_type TEXT NOT NULL,owner_id TEXT NOT NULL,state TEXT NOT NULL,data TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,repairs INTEGER NOT NULL DEFAULT 0,next_at TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS model_invocations(id TEXT PRIMARY KEY,job_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,model_id TEXT NOT NULL,model_version INTEGER NOT NULL,attempt INTEGER NOT NULL,state TEXT NOT NULL,input_tokens INTEGER,output_tokens INTEGER,cost REAL,duration_ms INTEGER,error_code TEXT,created_at TEXT NOT NULL,ended_at TEXT);
CREATE TABLE IF NOT EXISTS governance_limits(tenant_id TEXT PRIMARY KEY,daily_model_calls INTEGER NOT NULL DEFAULT 100,max_active_runs INTEGER NOT NULL DEFAULT 5,version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS model_jobs_queue ON model_jobs(state,next_at);
CREATE INDEX IF NOT EXISTS model_usage_tenant ON model_invocations(tenant_id,created_at);
'''
